create extension if not exists pgcrypto;
create table if not exists salons (id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, business_name text not null, slug text unique not null, description text, phone text, email text, address text, city text, country text default 'Nigeria', currency text default 'NGN', timezone text default 'Africa/Lagos', logo_url text, cover_image_url text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists salon_members (id uuid primary key default gen_random_uuid(), salon_id uuid references salons(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role text not null default 'staff' check(role in ('owner','manager','staff')), status text not null default 'active', created_at timestamptz default now(), unique(salon_id,user_id));
create table if not exists customers (id uuid primary key default gen_random_uuid(), salon_id uuid references salons(id) on delete cascade, first_name text not null, last_name text, phone text, email text, birthday date, notes text, preferred_stylist_id uuid, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists services (id uuid primary key default gen_random_uuid(), salon_id uuid references salons(id) on delete cascade, name text not null, description text, price numeric(12,2) not null default 0, duration_minutes integer not null default 60, deposit_amount numeric(12,2) default 0, active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists appointments (id uuid primary key default gen_random_uuid(), salon_id uuid references salons(id) on delete cascade, customer_id uuid references customers(id) on delete cascade, service_id uuid references services(id) on delete restrict, staff_id uuid references auth.users(id), start_time timestamptz not null, end_time timestamptz not null, status text default 'pending' check(status in ('pending','confirmed','completed','cancelled','no_show','rescheduled')), price numeric(12,2) default 0, deposit_amount numeric(12,2) default 0, balance_due numeric(12,2) default 0, notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists payments (id uuid primary key default gen_random_uuid(), salon_id uuid references salons(id) on delete cascade, customer_id uuid references customers(id) on delete cascade, appointment_id uuid references appointments(id) on delete set null, amount numeric(12,2) not null, currency text default 'NGN', method text default 'online', provider text, provider_reference text, status text default 'pending', paid_at timestamptz, created_at timestamptz default now());
create table if not exists expenses (id uuid primary key default gen_random_uuid(), salon_id uuid references salons(id) on delete cascade, category text, description text, amount numeric(12,2) not null, expense_date date default current_date, payment_method text, receipt_url text, created_by uuid references auth.users(id), created_at timestamptz default now());
create table if not exists inventory_items (id uuid primary key default gen_random_uuid(), salon_id uuid references salons(id) on delete cascade, name text not null, category text, unit text, quantity numeric(12,2) default 0, minimum_quantity numeric(12,2) default 0, cost_per_unit numeric(12,2) default 0, selling_price numeric(12,2) default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists inventory_transactions (id uuid primary key default gen_random_uuid(), inventory_item_id uuid references inventory_items(id) on delete cascade, type text, quantity numeric(12,2), reason text, created_by uuid references auth.users(id), created_at timestamptz default now());
create table if not exists marketing_campaigns (id uuid primary key default gen_random_uuid(), salon_id uuid references salons(id) on delete cascade, name text, campaign_type text, message text, audience_filter jsonb, status text default 'draft', created_at timestamptz default now());
create table if not exists messages (id uuid primary key default gen_random_uuid(), salon_id uuid references salons(id) on delete cascade, customer_id uuid references customers(id) on delete cascade, channel text, direction text, message text, status text, provider_message_id text, sent_at timestamptz, created_at timestamptz default now());
create table if not exists subscriptions (id uuid primary key default gen_random_uuid(), salon_id uuid unique references salons(id) on delete cascade, plan text default 'free', status text default 'active', provider text, provider_subscription_id text, current_period_start timestamptz, current_period_end timestamptz, created_at timestamptz default now());

alter table salons enable row level security; alter table salon_members enable row level security; alter table customers enable row level security; alter table services enable row level security; alter table appointments enable row level security; alter table payments enable row level security; alter table expenses enable row level security; alter table inventory_items enable row level security; alter table inventory_transactions enable row level security; alter table marketing_campaigns enable row level security; alter table messages enable row level security; alter table subscriptions enable row level security;
create or replace function public.user_salon_ids() returns setof uuid language sql security definer stable as $$ select salon_id from public.salon_members where user_id=auth.uid() and status='active'; $$;
create policy "members can read salons" on salons for select using (id in (select public.user_salon_ids()) or owner_id=auth.uid());
create policy "owners can create salons" on salons for insert with check (owner_id=auth.uid());
create policy "members can access members" on salon_members for all using (salon_id in (select public.user_salon_ids()) or user_id=auth.uid()) with check (salon_id in (select public.user_salon_ids()) or user_id=auth.uid());
create policy "salon scoped customers" on customers for all using (salon_id in (select public.user_salon_ids())) with check (salon_id in (select public.user_salon_ids()));
create policy "salon scoped services" on services for all using (salon_id in (select public.user_salon_ids())) with check (salon_id in (select public.user_salon_ids()));
create policy "salon scoped appointments" on appointments for all using (salon_id in (select public.user_salon_ids())) with check (salon_id in (select public.user_salon_ids()));
create policy "salon scoped payments" on payments for all using (salon_id in (select public.user_salon_ids())) with check (salon_id in (select public.user_salon_ids()));
create policy "salon scoped expenses" on expenses for all using (salon_id in (select public.user_salon_ids())) with check (salon_id in (select public.user_salon_ids()));
create policy "salon scoped inventory" on inventory_items for all using (salon_id in (select public.user_salon_ids())) with check (salon_id in (select public.user_salon_ids()));
create policy "salon scoped campaigns" on marketing_campaigns for all using (salon_id in (select public.user_salon_ids())) with check (salon_id in (select public.user_salon_ids()));
create policy "salon scoped messages" on messages for all using (salon_id in (select public.user_salon_ids())) with check (salon_id in (select public.user_salon_ids()));
create policy "salon scoped subscriptions" on subscriptions for select using (salon_id in (select public.user_salon_ids()));
create policy "members can create subscriptions" on subscriptions for insert with check (salon_id in (select public.user_salon_ids()));
create policy "members can update subscriptions" on subscriptions for update using (salon_id in (select public.user_salon_ids())) with check (salon_id in (select public.user_salon_ids()));
